<p><strong>Key difference:</strong> Nexon has a turbo-petrol and a diesel option; Brezza is petrol-only (with CNG). If you need a diesel or strong petrol performance, Nexon wins. The Brezza's mild-hybrid tech aids fuel economy in urban stop-start traffic.</p>

