    { q: "What is the best refrigerator under ₹30,000 in India?", a: "The LG 284L 3-Star Frost Free Double Door (around ₹29,990) is the best value double-door refrigerator under ₹30,000 in India. The Haier 320L (around ₹27,990) is an excellent budget alternative." }
